ALTER TABLE allowlist ADD COLUMN is_admin BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN quote_approve BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN quote_send BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN display_name VARCHAR(200) NOT NULL DEFAULT '', ADD COLUMN sender_title VARCHAR(200) NOT NULL DEFAULT '', ADD COLUMN sender_phone VARCHAR(80) NOT NULL DEFAULT '';
UPDATE allowlist SET is_admin=TRUE,quote_approve=TRUE,quote_send=TRUE,display_name='Joshua Herron',sender_title='Owner / Technical Lead',sender_phone='409-937-2798' WHERE email='josh@theitguys.us';
UPDATE allowlist SET quote_send=TRUE,display_name='Alanna Herron' WHERE email='alanna@theitguys.us';
CREATE TABLE config_quote_email (id INT PRIMARY KEY, subject_template VARCHAR(250) NOT NULL, body_template TEXT NOT NULL);
INSERT INTO config_quote_email (id,subject_template,body_template) VALUES (1,'Your Managed IT quote from The IT Guys - {QuoteId}','Hi {FirstName}, attached is your Managed IT quote ({MonthlyTotal}/month, {Onboarding} one-time onboarding). To accept, simply reply to this email saying you accept. We''ll then send the Master Services Agreement and Client Service Schedule{BAA phrase} for electronic signature. The quote is valid for 30 days. - {SenderName}, {SenderTitle}, The IT Guys LLC, {SenderPhone}');
ALTER TABLE quotes ADD COLUMN sent_at DATETIME NULL, ADD COLUMN sent_by VARCHAR(254) NULL, ADD COLUMN sent_to VARCHAR(254) NULL, ADD COLUMN sent_cc VARCHAR(254) NULL, ADD COLUMN sent_pdf_item_id VARCHAR(200) NULL, ADD COLUMN email_message_id VARCHAR(300) NULL;
CREATE TABLE quote_fills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quote_id BIGINT UNSIGNED NOT NULL, client_id VARCHAR(80) NOT NULL, document_key VARCHAR(30) NOT NULL, snapshot_hash VARCHAR(64) NOT NULL, drive_id VARCHAR(200) NOT NULL, item_id VARCHAR(200) NOT NULL, etag VARCHAR(500) NULL, report JSON NOT NULL, fields_json JSON NOT NULL, mode VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, actor VARCHAR(254) NOT NULL, web_url TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (quote_id) REFERENCES quotes(id));
CREATE TABLE quote_send_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quote_id BIGINT UNSIGNED NOT NULL, client_id VARCHAR(80) NOT NULL, fill_id BIGINT UNSIGNED NOT NULL, snapshot_hash VARCHAR(64) NOT NULL, status VARCHAR(30) NOT NULL, phase VARCHAR(30) NOT NULL, mode VARCHAR(20) NOT NULL, actor VARCHAR(254) NOT NULL, mailbox VARCHAR(254) NOT NULL, sent_to VARCHAR(254) NOT NULL, sent_cc VARCHAR(254) NULL, pdf_name VARCHAR(255) NOT NULL, pdf_item_id VARCHAR(200) NULL, pdf_bytes MEDIUMBLOB NOT NULL, email_json JSON NOT NULL, email_request_id VARCHAR(200) NULL, email_message_id VARCHAR(300) NULL, correlation_id VARCHAR(36) NOT NULL, error_message TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at DATETIME NULL, FOREIGN KEY (quote_id) REFERENCES quotes(id), FOREIGN KEY (fill_id) REFERENCES quote_fills(id));
CREATE TABLE quote_operation_locks (client_id VARCHAR(80) PRIMARY KEY, token VARCHAR(36) NOT NULL, operation VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
